use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let input_str = input.to_string();
    let mut result = Vec::new();
    let mut current_digit = 0;
    let mut is_negative = false;

    for c in input_str.chars() {
        if c == '-' {
            is_negative = !is_negative;
            continue;
        }

        if c.is_digit(16) {
            current_digit = (current_digit * 16) + c.to_digit(16).unwrap() as i64;
        } else {
            if current_digit != 0 {
                result.push(current_digit);
                current_digit = 0;
            }
        }
    }

    if current_digit != 0 {
        result.push(current_digit);
    }

    serde_json::Value::from(result)
}

fn main() {
    let input = serde_json::Value::from("{\"input\":\"00aF\",\"expected\":[0,175]}");
    let output = solve(input);
    println!("{:?}", output);
}
